from collections import deque

def solve(grid):
    if not grid or not grid[0]:
        return [row[:] for row in grid]

    rows = len(grid)
    cols = len(grid[0])

    # Find marker color (non-0, non-5)
    marker_color = None
    marker_positions = []
    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val != 0 and val != 5:
                marker_color = val
                marker_positions.append((r, c))

    if marker_color is None:
        return [row[:] for row in grid]

    # Find connected components of markers (4-connected)
    marker_visited = set()
    marker_components = []
    for r, c in marker_positions:
        if (r, c) not in marker_visited:
            queue = deque([(r, c)])
            marker_visited.add((r, c))
            component = []
            while queue:
                cr, cc = queue.popleft()
                component.append((cr, cc))
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in marker_visited:
                        if grid[nr][nc] == marker_color:
                            marker_visited.add((nr, nc))
                            queue.append((nr, nc))
            marker_components.append(component)

    K = len(marker_components)
    N = len(marker_positions)

    # Find connected components of 5s
    five_visited = [[False] * cols for _ in range(rows)]
    five_components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 5 and not five_visited[r][c]:
                queue = deque([(r, c)])
                five_visited[r][c] = True
                component = []
                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols and not five_visited[nr][nc]:
                            if grid[nr][nc] == 5:
                                five_visited[nr][nc] = True
                                queue.append((nr, nc))
                if len(component) == N:
                    five_components.append(component)

    # Sort by min_row, then min_col to select which ones to replace
    five_components.sort(key=lambda comp: (min(r for r, c in comp), min(c for r, c in comp)))

    # Select up to K components
    selected_components = five_components[:K]

    # Create output
    output = [row[:] for row in grid]

    # Replace selected 5-components with marker color
    for component in selected_components:
        for r, c in component:
            output[r][c] = marker_color

    # Clear original markers
    for r, c in marker_positions:
        output[r][c] = 0

    return output
